using System;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;
namespace CircuitoStudio {
public sealed class FaultLoopsForm:Form {
Project project;Circuit circuit;LoopSource source;LoopFaultCase fault;List<Action> readers=new List<Action>();TextBox result=new TextBox{Dock=DockStyle.Bottom,Height=230,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical};public bool Changed{get;private set;}
public FaultLoopsForm(Project p,Circuit c){project=p;circuit=c;source=p.LoopSource==null?new LoopSource{LineVoltageV=p.Source.LineVoltage,FrequencyHz=p.Frequency}:p.LoopSource.Copy();fault=c.LoopFault==null?new LoopFaultCase():c.LoopFault.Copy();Text="Laços de falta — "+c.Id;Size=new Size(1320,850);MinimumSize=new Size(1080,700);Font=new Font("Segoe UI",10);var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=2};layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));layout.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,35));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.Controls.Add(new Label{Text="Fonte: equivalente estrela desacoplado explícito",Dock=DockStyle.Fill},0,0);layout.Controls.Add(new Label{Text="Ponto de falta: fim do circuito; IT2 exige outro condutor ativo",Dock=DockStyle.Fill},1,0);layout.Controls.Add(TypedFields.Create(source,readers),0,1);layout.Controls.Add(TypedFields.Create(fault,readers),1,1);var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=45};Add(bar,"Calcular cópia",()=>EvaluateDraft(false));Add(bar,"Salvar fonte e caso",()=>EvaluateDraft(true));Add(bar,"Remover caso",()=>{circuit.LoopFault=null;Changed=true;result.Text="Caso removido; equivalente da fonte preservado.";});Controls.Add(layout);Controls.Add(result);Controls.Add(bar);result.Text="Nenhuma alteração até salvar. Declare R/X de estrela e retornos; o curto3F não preenche neutro/PE/PEN automaticamente. R/X vazios são desconhecidos; zero é ideal explícito. N/PE/PEN dos cabos vêm do cadastro tipado e das seções de retorno selecionadas. A corrente nominal do modelo não comprova seção/continuidade/IMD/tempo ou segurança. Fugas IT: condutância em siemens e capacitância em nF POR FASE, concentradas no barramento do ponto de falta; equivalência precisa ser documentada.";}
void Add(Control bar,string label,Action action){var button=new Button{Text=label,AutoSize=true,Height=32};button.Click+=(s,e)=>{try{action();}catch(Exception ex){result.Text="Nenhuma alteração. "+ex.Message;}};bar.Controls.Add(button);}
public FaultLoopResult EvaluateDraft(bool commit){foreach(var read in readers)read();source.Validate();fault.Validate();var oldSource=project.LoopSource;var oldFault=circuit.LoopFault;project.LoopSource=source.Copy();circuit.LoopFault=fault.Copy();bool accepted=false;try{project.Validate();var evaluated=FaultLoops.Evaluate(project,circuit,circuit.LoopFault);result.Text=evaluated.Detail;if(commit){Changed=true;accepted=true;}return evaluated;}finally{if(!accepted){project.LoopSource=oldSource;circuit.LoopFault=oldFault;}}}
}
partial class Studio {void ConfigureFaultLoops(){if(circuit==null)throw new InvalidOperationException("Selecione um circuito.");using(var form=new FaultLoopsForm(project,circuit)){form.ShowDialog(this);if(form.Changed)Change();}}}
}
